cypress_script:
describe('Customer Registration Form', () => {
  it('should register a new user successfully', () => {
    cy.visit('https://parabank.parasoft.com/parabank/register.htm');
    cy.get('input#customer.firstName').type('John');
    cy.get('input#customer.lastName').type('Doe');
    cy.get('input#customer.address.street').type('123 Main St');
    cy.get('input#customer.address.city').type('Anytown');
    cy.get('input#customer.address.state').type('CA');
    cy.get('input#customer.address.zipCode').type('12345');
    cy.get('input#customer.phoneNumber').type('1234567890');
    cy.get('input#customer.ssn').type('123-45-6789');
    cy.get('input#customer.username').type('johndoe');
    cy.get('input#customer.password').type('password123');
    cy.get('input#repeatedPassword').type('password123');
    cy.get('input[value="Register"]').click();
    cy.url().should('not.include', 'register.htm');
  });

  it('should not allow registration with empty required fields', () => {
    cy.visit('https://parabank.parasoft.com/parabank/register.htm');
    cy.get('input[value="Register"]').click();
    cy.url().should('include', 'register.htm');
  });
});

playwright_script:
import { test } from '@playwright/test';

test.describe('Customer Registration Form', () => {
  test('should register a new user successfully', async ({ page }) => {
    await page.goto('https://parabank.parasoft.com/parabank/register.htm');
    await page.fill('input#customer.firstName', 'John');
    await page.fill('input#customer.lastName', 'Doe');
    await page.fill('input#customer.address.street', '123 Main St');
    await page.fill('input#customer.address.city', 'Anytown');
    await page.fill('input#customer.address.state', 'CA');
    await page.fill('input#customer.address.zipCode', '12345');
    await page.fill('input#customer.phoneNumber', '1234567890');
    await page.fill('input#customer.ssn', '123-45-6789');
    await page.fill('input#customer.username', 'johndoe');
    await page.fill('input#customer.password', 'password123');
    await page.fill('input#repeatedPassword', 'password123');
    await page.click('input[value="Register"]');
    await page.waitForURL('**/*'); // wait for navigation
  });

  test('should not allow registration with empty required fields', async ({ page }) => {
    await page.goto('https://parabank.parasoft.com/parabank/register.htm');
    await page.click('input[value="Register"]');
    await page.waitForURL('**/register.htm');
  });
});
